#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

int global_var = 0;

// 进程创建示例
void demo_fork() {
    pid_t pid = fork();
    if (pid == 0) {
        // 子进程
        global_var = 100;
        printf("Child process: global_var = %d, pid = %d\n", global_var, getpid());
        exit(0);
    } else {
        // 父进程
        wait(NULL);
        // 子进程修改不会影响父进程的 global_var
        printf("Parent process: global_var = %d, pid = %d\n", global_var, getpid());
    }
}

// 线程创建示例
void* thread_func(void* arg) {
    global_var = 200;
    printf("Thread: global_var = %d\n", global_var);
    return NULL;
}

demo_fork();

pthread_t tid;
pthread_create(&tid, NULL, thread_func, NULL);
pthread_join(tid, NULL);
// 线程修改了共享的 global_var
printf("Main thread: global_var = %d\n", global_var);
// 输出: global_var = 200
